import sys

# Read input
n, k = map(int, sys.stdin.readline().split())

# Calculate the minimum m
m = n * k

# Generate sets
sets = []
for i in range(1, m + 1, k):
    for j in range(i + k, m + 1, k):
        for a in range(j + k, m + 1, k):
            for b in range(a + k, m + 1, k):
                sets.append([i, j, a, b])
                if len(sets) == n:
                    break
            if len(sets) == n:
                break
        if len(sets) == n:
            break
    if len(sets) == n:
        break

# Output the result
print(m)
for s in sets:
    print(*s)
